@MainActor
final class MacFillView: NSView {
  private let fill: NSColor
  private let border: Bool

  init(fill: NSColor, radius: CGFloat, border: Bool = false) {
    self.fill = fill
    self.border = border
    super.init(frame: .zero)
    wantsLayer = true
