    model.replyCapability = Capability(machineId: "m", cliType: "builtin", agentType: "codex", models: [CapabilityChoice(id: "gpt", name: "GPT")], reasoningEfforts: ["gpt": ["high", "low"]])
    model.replyChoice = ModelChoice(modelId: "gpt", effort: "high")
